# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: digest
def digest(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    return [v * v for v in xs[1:]]

# region: intake
def intake(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(shape(intake(gather(digest(render(raw))))))

